-- >>> BEGIN SOURCE 009_has_role_function.sql (blob 9c876b66a0ec69b114b28a4a17598d94e3abbda9)
-- Role check helper for RLS policies (uses auth.uid() + user_roles)

create or replace function has_role(role_name text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from user_roles ur
    join roles r on r.id = ur.role_id
    where ur.user_id = auth.uid()
    and r.name = role_name
  );
$$;
-- <<< END SOURCE 009_has_role_function.sql

-- >>> BEGIN SOURCE 010_is_school_member_function.sql (blob 656cc136a440e911d36673759b2abccead21d9ab)
-- School membership check for RLS (family, teacher, CEO, or school leader)

create or replace function is_school_member(school uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from students s
    where s.school_id = school
    and exists (
      select 1
      from student_family_link sfl
      where sfl.student_id = s.id
      and sfl.user_id = auth.uid()
    )
  )
  or exists (
    select 1
    from classes c
    where c.school_id = school
    and c.teacher_id = auth.uid()
  )
  or has_role('CEO')
  or has_role('SCHOOL_LEADER');
$$;
-- <<< END SOURCE 010_is_school_member_function.sql

