create policy campuses_select
on public.campuses
for select
using (can_access_school(school_id));

create policy campuses_insert
on public.campuses
for insert
with check (can_access_school(school_id));

create policy campuses_update
on public.campuses
for update
using (can_access_school(school_id))
with check (can_access_school(school_id));

