-- =========================================
-- API GRANTS + SCHEMA RELOAD (058)
-- Supabase no longer auto-exposes new tables to
-- anon/authenticated/service_role without explicit GRANTs.
-- Idempotent: safe to re-run.
-- =========================================

grant usage on schema public to postgres, anon, authenticated, service_role;

grant select, insert, update, delete on all tables in schema public to authenticated;
grant select on all tables in schema public to anon;
grant all on all tables in schema public to service_role;

grant usage, select on all sequences in schema public to authenticated;
grant all on all sequences in schema public to service_role;

alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

alter default privileges in schema public
  grant select on tables to anon;

alter default privileges in schema public
  grant all on tables to service_role;

alter default privileges in schema public
  grant usage, select on sequences to authenticated;

alter default privileges in schema public
  grant all on sequences to service_role;

-- RLS helper functions must be executable by API roles
grant execute on all functions in schema public to authenticated, anon, service_role;

notify pgrst, 'reload schema';
-- <<< END SOURCE 058_api_grants_and_schema_reload.sql

-- >>> BEGIN SOURCE 059_grade_funding_programs.sql (blob ada28ba1fa1ee439dac1b401cec41067fecf25fc)
-- =========================================
-- GRADE DROPDOWNS + NORMALIZED FUNDING SOURCES (059)
-- Multi-select funding via junction tables; migrate legacy column.
-- Idempotent: safe to re-run after partial apply.
-- =========================================

-- ---------------------------------------------------------------------------
-- Funding source lookup + junction tables
-- ---------------------------------------------------------------------------

create table if not exists public.funding_sources (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  label text not null,
  sort_order int not null default 0
);

insert into public.funding_sources (code, label, sort_order) values
  ('parent_pay', 'Parent Pay', 1),
  ('family_scholarship', 'Family Scholarship', 2),
  ('school_scholarship', 'School Scholarship', 3),
  ('outside_scholarship', 'Outside Scholarship', 4),
  ('esa', 'ESA', 5),
  ('step_up_for_students', 'Step Up For Students', 6),
  ('mckay_scholarship', 'McKay Scholarship', 7),
  ('fes_ua', 'FES-UA', 8),
  ('district_placement', 'District Placement', 9),
  ('vocational_rehabilitation', 'Vocational Rehabilitation', 10),
  ('medicaid_waiver', 'Medicaid Waiver', 11),
  ('state_agency_placement', 'State Agency Placement', 12),
  ('grant_funded', 'Grant Funded', 13),
  ('corporate_sponsorship', 'Corporate Sponsorship', 14),
  ('other', 'Other', 15)
on conflict (code) do update set
  label = excluded.label,
  sort_order = excluded.sort_order;

create table if not exists public.admissions_lead_funding_sources (
  lead_id uuid not null references public.admissions_leads(id) on delete cascade,
  funding_source_id uuid not null references public.funding_sources(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (lead_id, funding_source_id)
);

create index if not exists idx_admissions_lead_funding_sources_lead
  on public.admissions_lead_funding_sources(lead_id);

create index if not exists idx_admissions_lead_funding_sources_source
  on public.admissions_lead_funding_sources(funding_source_id);

create table if not exists public.student_funding_sources (
  student_id uuid not null references public.students(id) on delete cascade,
  funding_source_id uuid not null references public.funding_sources(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (student_id, funding_source_id)
);

create index if not exists idx_student_funding_sources_student
  on public.student_funding_sources(student_id);

create index if not exists idx_student_funding_sources_source
  on public.student_funding_sources(funding_source_id);

-- Migrate legacy admissions_leads.funding_source into junction table
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'admissions_leads'
      and column_name = 'funding_source'
  ) then
    insert into public.admissions_lead_funding_sources (lead_id, funding_source_id)
    select
      al.id,
      fs.id
    from public.admissions_leads al
    join public.funding_sources fs on fs.code = case al.funding_source
      when 'private_pay' then 'parent_pay'
      when 'esa' then 'esa'
      when 'voucher' then 'step_up_for_students'
      when 'tax_credit_scholarship' then 'family_scholarship'
      when 'school_scholarship' then 'school_scholarship'
      else coalesce(al.funding_source, 'other')
    end
    where al.funding_source is not null
    on conflict do nothing;

    alter table public.admissions_leads drop constraint if exists admissions_leads_funding_source_check;
    alter table public.admissions_leads drop column if exists funding_source;
  end if;
end $$;

drop index if exists public.idx_admissions_leads_funding_source;

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------

alter table public.funding_sources enable row level security;

drop policy if exists funding_sources_read on public.funding_sources;
create policy funding_sources_read
on public.funding_sources
for select
to authenticated
using (true);

alter table public.admissions_lead_funding_sources enable row level security;

drop policy if exists admissions_lead_funding_sources_staff_all on public.admissions_lead_funding_sources;
create policy admissions_lead_funding_sources_staff_all
on public.admissions_lead_funding_sources
for all
using (
  can_access_school((
    select school_id from public.admissions_leads where id = lead_id
  ))
)
with check (
  can_access_school((
    select school_id from public.admissions_leads where id = lead_id
  ))
);

alter table public.student_funding_sources enable row level security;

drop policy if exists student_funding_sources_staff_all on public.student_funding_sources;
create policy student_funding_sources_staff_all
on public.student_funding_sources
for all
using (
  can_access_school((
    select school_id from public.students where id = student_id
  ))
)
with check (
  can_access_school((
    select school_id from public.students where id = student_id
  ))
);

-- ---------------------------------------------------------------------------
-- API grants for new tables
-- ---------------------------------------------------------------------------

grant select on public.funding_sources to authenticated, anon;
grant select, insert, update, delete on public.admissions_lead_funding_sources to authenticated;
grant select, insert, update, delete on public.student_funding_sources to authenticated;
grant all on public.funding_sources to service_role;
grant all on public.admissions_lead_funding_sources to service_role;
grant all on public.student_funding_sources to service_role;

notify pgrst, 'reload schema';
-- <<< END SOURCE 059_grade_funding_programs.sql

-- >>> BEGIN SOURCE 060_funding_source_category.sql (blob 5a1c24ccfc4f412f984310635d3c30d7914f98c0)
-- =========================================
-- FUNDING SOURCE CATEGORY (060)
-- Adds funding_source_category for grouped reporting.
-- Idempotent: safe to re-run after partial apply.
-- =========================================

alter table public.funding_sources
  add column if not exists funding_source_category text;

update public.funding_sources set funding_source_category = case code
  when 'parent_pay' then 'parent'
  when 'family_scholarship' then 'scholarship'
  when 'school_scholarship' then 'scholarship'
  when 'outside_scholarship' then 'scholarship'
  when 'esa' then 'state_funding'
  when 'step_up_for_students' then 'state_funding'
  when 'mckay_scholarship' then 'state_funding'
  when 'fes_ua' then 'state_funding'
  when 'district_placement' then 'public_placement'
  when 'vocational_rehabilitation' then 'government_program'
  when 'medicaid_waiver' then 'government_program'
  when 'state_agency_placement' then 'government_program'
  when 'grant_funded' then 'scholarship'
  when 'corporate_sponsorship' then 'corporate'
  when 'other' then 'other'
  else 'other'
end
where funding_source_category is null;

alter table public.funding_sources
  alter column funding_source_category set not null;

alter table public.funding_sources
  drop constraint if exists funding_sources_category_check;

alter table public.funding_sources
  add constraint funding_sources_category_check
  check (funding_source_category in (
    'parent',
    'scholarship',
    'state_funding',
    'public_placement',
    'government_program',
    'corporate',
    'other'
  ));

create index if not exists idx_funding_sources_category
  on public.funding_sources(funding_source_category);

notify pgrst, 'reload schema';
-- <<< END SOURCE 060_funding_source_category.sql

-- >>> BEGIN SOURCE 061_admissions_workflow_automation.sql (blob 67c6d87f18455f472ac808081a4f6793c1341bfc)
-- =========================================
-- ADMISSIONS WORKFLOW AUTOMATION
-- stage_entered_at, stage history, backfill
-- Idempotent: safe to re-run
-- =========================================

-- Track when the lead entered its current stage
alter table public.admissions_leads
  add column if not exists stage_entered_at timestamptz not null default now();

update public.admissions_leads
set stage_entered_at = coalesce(created_at, now())
where stage_entered_at is null
   or stage_entered_at = created_at;

-- Stage change audit trail
create table if not exists public.admissions_lead_stage_history (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.admissions_leads(id) on delete cascade,
  previous_stage text,
  new_stage text not null,
  changed_by uuid references public.users(id) on delete set null,
  changed_at timestamptz not null default now()
);

create index if not exists idx_lead_stage_history_lead_id
  on public.admissions_lead_stage_history(lead_id);

create index if not exists idx_lead_stage_history_changed_at
  on public.admissions_lead_stage_history(changed_at desc);

-- Backfill initial stage entry for existing leads without history
insert into public.admissions_lead_stage_history (lead_id, previous_stage, new_stage, changed_at)
select al.id, null, al.lead_stage, coalesce(al.created_at, now())
from public.admissions_leads al
where not exists (
  select 1
  from public.admissions_lead_stage_history h
  where h.lead_id = al.id
);

-- RLS
alter table public.admissions_lead_stage_history enable row level security;

drop policy if exists admissions_lead_stage_history_staff_all on public.admissions_lead_stage_history;

create policy admissions_lead_stage_history_staff_all
on public.admissions_lead_stage_history
for all
using (can_access_school(school_id_for_admission_lead(lead_id)))
with check (can_access_school(school_id_for_admission_lead(lead_id)));

drop policy if exists admissions_lead_stage_history_guardian_select on public.admissions_lead_stage_history;

create policy admissions_lead_stage_history_guardian_select
on public.admissions_lead_stage_history
for select
using (is_guardian_of_lead(lead_id));
-- <<< END SOURCE 061_admissions_workflow_automation.sql

-- >>> BEGIN SOURCE 062_admissions_stage_entered_at_trigger.sql (blob 78d4da38579e7e2b1057f8107aa8de4a598b4d36)
-- =========================================
-- ADMISSIONS stage_entered_at trigger + schema reload (062)
-- Keeps stage_entered_at in sync when lead_stage changes so the
-- app never needs to POST the column through PostgREST.
-- Idempotent: safe to re-run
-- =========================================

create or replace function public.set_admissions_lead_stage_entered_at()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if new.stage_entered_at is null then
      new.stage_entered_at := coalesce(new.created_at, now());
    end if;
  elsif tg_op = 'UPDATE' and old.lead_stage is distinct from new.lead_stage then
    new.stage_entered_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists trg_admissions_leads_stage_entered_at on public.admissions_leads;

create trigger trg_admissions_leads_stage_entered_at
  before insert or update on public.admissions_leads
  for each row
  execute function public.set_admissions_lead_stage_entered_at();

-- 061 added stage_entered_at but did not reload PostgREST; reads/writes fail until cache refreshes.
notify pgrst, 'reload schema';
-- <<< END SOURCE 062_admissions_stage_entered_at_trigger.sql

-- >>> BEGIN SOURCE 063_funding_junction_api.sql (blob 0123bdd061a9a0b2da2e82e5f849746d2b5bfec5)
-- =========================================
-- FUNDING JUNCTION API (063)
-- Flat SQL accessors for junction tables when PostgREST
-- does not expose admissions_lead_funding_sources /
-- student_funding_sources on the Data API.
-- Idempotent: safe to re-run.
-- =========================================

grant usage on schema public to postgres, anon, authenticated, service_role;

grant select on table public.funding_sources to authenticated, anon;
grant select, insert, update, delete on table public.admissions_lead_funding_sources to authenticated;
grant select, insert, update, delete on table public.student_funding_sources to authenticated;
grant all on table public.funding_sources to service_role;
grant all on table public.admissions_lead_funding_sources to service_role;
grant all on table public.student_funding_sources to service_role;

-- Named composite types are required for PostgREST to expose set-returning RPCs.
-- PostgreSQL does not support CREATE TYPE IF NOT EXISTS; use catalog checks
-- (same pattern as 064_funding_junction_rpc_fix.sql).
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_namespace n
      ON n.oid = t.typnamespace
    WHERE t.typname = 'lead_funding_link'
      AND n.nspname = 'public'
  ) THEN
    CREATE TYPE public.lead_funding_link AS (
      lead_id uuid,
      funding_source_id uuid
    );
  END IF;
END
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_namespace n
      ON n.oid = t.typnamespace
    WHERE t.typname = 'student_funding_link'
      AND n.nspname = 'public'
  ) THEN
    CREATE TYPE public.student_funding_link AS (
      student_id uuid,
      funding_source_id uuid
    );
  END IF;
END
$$;

grant usage on type public.lead_funding_link to authenticated, anon, service_role;
grant usage on type public.student_funding_link to authenticated, anon, service_role;

-- Flat read: admissions lead junction rows (no embed / relationship syntax)
-- Signature: list_admissions_lead_funding_sources(p_lead_ids uuid[])
create or replace function public.list_admissions_lead_funding_sources(p_lead_ids uuid[])
returns setof public.lead_funding_link
language sql
stable
security invoker
set search_path = public
as $$
  select alfs.lead_id, alfs.funding_source_id
  from public.admissions_lead_funding_sources alfs
  where alfs.lead_id = any (p_lead_ids);
$$;

-- Flat write: replace all funding links for one lead
-- Signature: replace_admissions_lead_funding_sources(p_lead_id uuid, p_funding_source_ids uuid[])
create or replace function public.replace_admissions_lead_funding_sources(
  p_lead_id uuid,
  p_funding_source_ids uuid[]
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.admissions_lead_funding_sources
  where lead_id = p_lead_id;

  if coalesce(array_length(p_funding_source_ids, 1), 0) = 0 then
    return;
  end if;

  insert into public.admissions_lead_funding_sources (lead_id, funding_source_id)
  select p_lead_id, fs_id
  from unnest(p_funding_source_ids) as fs_id
  on conflict do nothing;
end;
$$;

-- Flat read: student junction rows
-- Signature: list_student_funding_sources(p_student_ids uuid[])
create or replace function public.list_student_funding_sources(p_student_ids uuid[])
returns setof public.student_funding_link
language sql
stable
security invoker
set search_path = public
as $$
  select sfs.student_id, sfs.funding_source_id
  from public.student_funding_sources sfs
  where sfs.student_id = any (p_student_ids);
$$;

-- Flat write: replace all funding links for one student
-- Signature: replace_student_funding_sources(p_student_id uuid, p_funding_source_ids uuid[])
create or replace function public.replace_student_funding_sources(
  p_student_id uuid,
  p_funding_source_ids uuid[]
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.student_funding_sources
  where student_id = p_student_id;

  if coalesce(array_length(p_funding_source_ids, 1), 0) = 0 then
    return;
  end if;

  insert into public.student_funding_sources (student_id, funding_source_id)
  select p_student_id, fs_id
  from unnest(p_funding_source_ids) as fs_id
  on conflict do nothing;
end;
$$;

