-- >>> BEGIN SOURCE 090_release7_parent_student_experience_foundation.sql (blob bafd85b55b728740c979b0a5dc68ec384d9b6d9b)
-- =========================================
-- RELEASE 7: PARENT & STUDENT EXPERIENCE PLATFORM
-- Extends SSIS, scheduling, finance, meetings — idempotent
-- =========================================

-- ---------------------------------------------------------------------------
-- 1. Unified parent/student access helpers
-- ---------------------------------------------------------------------------

create or replace function public.is_parent_of_student(check_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select
    exists (
      select 1 from public.student_family_link sfl
      where sfl.student_id = check_student_id and sfl.user_id = auth.uid()
    )
    or exists (
      select 1 from public.students s
      join public.guardians g on g.family_id = s.family_id
      where s.id = check_student_id and g.user_id = auth.uid()
    );
$$;

create or replace function public.can_access_student_record(check_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select
    is_enterprise_admin()
    or exists (
      select 1 from public.students s
      where s.id = check_student_id and can_access_school(s.school_id)
    )
    or exists (
      select 1 from public.student_family_link sfl
      where sfl.student_id = check_student_id and sfl.user_id = auth.uid()
    )
    or exists (
      select 1 from public.students s
      join public.guardians g on g.family_id = s.family_id
      where s.id = check_student_id and g.user_id = auth.uid()
    )
    or exists (
      select 1 from public.students s
      where s.id = check_student_id and s.user_id = auth.uid()
    );
$$;

-- ---------------------------------------------------------------------------
-- 2. Secure messaging
-- ---------------------------------------------------------------------------

create table if not exists public.portal_conversations (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  family_id uuid references public.families(id) on delete set null,
  category text not null default 'general'
    check (category in ('general', 'teacher', 'therapist', 'finance', 'admissions', 'school_leader', 'hr')),
  subject text not null,
  status text not null default 'open'
    check (status in ('open', 'closed', 'archived')),
  created_by_user_id uuid references public.users(id) on delete set null,
  assigned_staff_user_id uuid references public.users(id) on delete set null,
  last_message_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_portal_conversations_student on public.portal_conversations(student_id, status);
create index if not exists idx_portal_conversations_family on public.portal_conversations(family_id);

drop trigger if exists portal_conversations_set_updated_at on public.portal_conversations;
create trigger portal_conversations_set_updated_at
  before update on public.portal_conversations
  for each row execute function public.trigger_set_updated_at();

create table if not exists public.portal_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.portal_conversations(id) on delete cascade,
  sender_user_id uuid references public.users(id) on delete set null,
  body text not null,
  message_category text not null default 'general'
    check (message_category in ('general', 'attendance', 'academic', 'behavior', 'financial', 'document', 'meeting')),
  translation_locale text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_portal_messages_conversation on public.portal_messages(conversation_id, created_at desc);

create table if not exists public.portal_message_reads (
  message_id uuid not null references public.portal_messages(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  read_at timestamptz not null default now(),
  primary key (message_id, user_id)
);

create table if not exists public.portal_message_attachments (
  id uuid primary key default gen_random_uuid(),
  message_id uuid not null references public.portal_messages(id) on delete cascade,
  file_name text not null,
  storage_path text not null,
  mime_type text,
  file_size_bytes bigint,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 3. Family notifications (post-enrollment)
-- ---------------------------------------------------------------------------

create table if not exists public.portal_family_notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  family_id uuid references public.families(id) on delete cascade,
  student_id uuid references public.students(id) on delete cascade,
  category text not null default 'general'
    check (category in (
      'general', 'message', 'attendance', 'academic', 'behavior', 'financial',
      'document', 'meeting', 'scholarship', 'state_funding', 'announcement', 'task'
    )),
  title text not null,
  body text not null,
  href text,
  is_read boolean not null default false,
  read_at timestamptz,
  delivery_method text not null default 'portal'
    check (delivery_method in ('portal', 'email', 'sms', 'push')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_portal_family_notifications_user
  on public.portal_family_notifications(user_id, is_read, created_at desc);

-- ---------------------------------------------------------------------------
-- 4. Family forms center
-- ---------------------------------------------------------------------------

create table if not exists public.portal_form_templates (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  form_key text not null,
  title text not null,
  description text,
  form_type text not null default 'custom'
    check (form_type in (
      're_enrollment', 'medical', 'emergency_contact', 'transportation',
      'technology', 'media_release', 'financial', 'scholarship', 'state_funding', 'custom'
    )),
  requires_signature boolean not null default false,
  is_active boolean not null default true,
  schema jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (school_id, form_key)
);

drop trigger if exists portal_form_templates_set_updated_at on public.portal_form_templates;
create trigger portal_form_templates_set_updated_at
  before update on public.portal_form_templates
  for each row execute function public.trigger_set_updated_at();

create table if not exists public.portal_form_submissions (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.portal_form_templates(id) on delete cascade,
  student_id uuid references public.students(id) on delete set null,
  family_id uuid references public.families(id) on delete set null,
  submitted_by_user_id uuid references public.users(id) on delete set null,
  answers jsonb not null default '{}'::jsonb,
  signature_id uuid references public.platform_digital_signatures(id) on delete set null,
  status text not null default 'submitted'
    check (status in ('draft', 'submitted', 'approved', 'rejected')),
  submitted_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create index if not exists idx_portal_form_submissions_family on public.portal_form_submissions(family_id, submitted_at desc);

-- ---------------------------------------------------------------------------
-- 5. Parent conference center extensions
-- ---------------------------------------------------------------------------

alter table public.student_instructional_meetings
  add column if not exists parent_visible boolean not null default true;

alter table public.student_instructional_meetings
  add column if not exists parent_response_status text
    check (parent_response_status is null or parent_response_status in ('pending', 'accepted', 'declined', 'rescheduled'));

alter table public.student_instructional_meetings
  add column if not exists virtual_meeting_url text;

alter table public.student_instructional_meetings
  add column if not exists parent_notes text;

create table if not exists public.portal_conference_requests (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete cascade,
  meeting_id uuid references public.student_instructional_meetings(id) on delete set null,
  requested_by_user_id uuid references public.users(id) on delete set null,
  preferred_times jsonb not null default '[]'::jsonb,
  status text not null default 'pending'
    check (status in ('pending', 'accepted', 'declined', 'cancelled')),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_portal_conference_requests_student
  on public.portal_conference_requests(student_id, status);

drop trigger if exists portal_conference_requests_set_updated_at on public.portal_conference_requests;
create trigger portal_conference_requests_set_updated_at
  before update on public.portal_conference_requests
  for each row execute function public.trigger_set_updated_at();

-- ---------------------------------------------------------------------------
-- 6. Calendar export tokens (ICS)
-- ---------------------------------------------------------------------------

create table if not exists public.portal_calendar_export_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  token_hash text not null unique,
  label text,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index if not exists idx_portal_calendar_tokens_user on public.portal_calendar_export_tokens(user_id);

-- ---------------------------------------------------------------------------
-- 7. Portal permissions
-- ---------------------------------------------------------------------------

insert into public.platform_permissions (permission_key, name, description, module, category, sort_order)
values
  ('portal.messaging', 'Portal Messaging', 'Send and receive secure portal messages', 'parent_portal', 'portal', 210),
  ('portal.notifications.manage', 'Portal Notifications', 'Manage family notification preferences', 'parent_portal', 'portal', 211),
  ('portal.forms.submit', 'Portal Forms', 'Submit family forms and signatures', 'parent_portal', 'portal', 212),
  ('portal.conferences', 'Portal Conferences', 'Request and manage parent conferences', 'parent_portal', 'portal', 213)
on conflict (permission_key) do nothing;

insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name = 'PARENT'
  and p.permission_key in (
    'portal.messaging', 'portal.notifications.manage', 'portal.forms.submit', 'portal.conferences'
  )
on conflict do nothing;

-- Seed default family form templates per school (idempotent via form_key)
insert into public.portal_form_templates (school_id, form_key, title, description, form_type, requires_signature)
select s.id, 'annual_re_enrollment', 'Annual Re-Enrollment', 'Confirm enrollment for the upcoming school year.', 're_enrollment', true
from public.schools s
where not exists (
  select 1 from public.portal_form_templates t
  where t.school_id = s.id and t.form_key = 'annual_re_enrollment'
);

insert into public.portal_form_templates (school_id, form_key, title, description, form_type, requires_signature)
select s.id, 'emergency_contacts', 'Emergency Contact Update', 'Update emergency contacts and authorized pickups.', 'emergency_contact', false
from public.schools s
where not exists (
  select 1 from public.portal_form_templates t
  where t.school_id = s.id and t.form_key = 'emergency_contacts'
);

insert into public.portal_form_templates (school_id, form_key, title, description, form_type, requires_signature)
select s.id, 'media_release', 'Media Release', 'Photo and video release for school communications.', 'media_release', true
from public.schools s
where not exists (
  select 1 from public.portal_form_templates t
  where t.school_id = s.id and t.form_key = 'media_release'
);
-- <<< END SOURCE 090_release7_parent_student_experience_foundation.sql

-- >>> BEGIN SOURCE 091_release7_parent_student_experience_rls.sql (blob d9631ef4811a97ac9ba681fed5f9672bddd356b1)
-- =========================================
-- RELEASE 7 RLS: Parent & Student Experience
-- =========================================

alter table public.portal_conversations enable row level security;
alter table public.portal_messages enable row level security;
alter table public.portal_message_reads enable row level security;
alter table public.portal_message_attachments enable row level security;
alter table public.portal_family_notifications enable row level security;
alter table public.portal_form_templates enable row level security;
alter table public.portal_form_submissions enable row level security;
alter table public.portal_conference_requests enable row level security;
alter table public.portal_calendar_export_tokens enable row level security;

-- Conversations: parents of student, staff with school access, message participants
drop policy if exists portal_conversations_select on public.portal_conversations;
create policy portal_conversations_select on public.portal_conversations
for select to authenticated using (
  is_parent_of_student(student_id)
  or can_access_school(school_id)
  or created_by_user_id = auth.uid()
  or assigned_staff_user_id = auth.uid()
);

drop policy if exists portal_conversations_insert on public.portal_conversations;
create policy portal_conversations_insert on public.portal_conversations
for insert to authenticated with check (
  (is_parent_of_student(student_id) and has_permission('portal.messaging'))
  or can_access_school(school_id)
);

drop policy if exists portal_conversations_update on public.portal_conversations;
create policy portal_conversations_update on public.portal_conversations
for update to authenticated using (
  is_parent_of_student(student_id) or can_access_school(school_id)
);

-- Messages
drop policy if exists portal_messages_select on public.portal_messages;
create policy portal_messages_select on public.portal_messages
for select to authenticated using (
  exists (
    select 1 from public.portal_conversations c
    where c.id = conversation_id
      and (is_parent_of_student(c.student_id) or can_access_school(c.school_id))
  )
);

drop policy if exists portal_messages_insert on public.portal_messages;
create policy portal_messages_insert on public.portal_messages
for insert to authenticated with check (
  exists (
    select 1 from public.portal_conversations c
    where c.id = conversation_id
      and (
        (is_parent_of_student(c.student_id) and has_permission('portal.messaging'))
        or can_access_school(c.school_id)
      )
  )
);

-- Message reads
drop policy if exists portal_message_reads_all on public.portal_message_reads;
create policy portal_message_reads_all on public.portal_message_reads
for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Attachments
drop policy if exists portal_message_attachments_select on public.portal_message_attachments;
create policy portal_message_attachments_select on public.portal_message_attachments
for select to authenticated using (
  exists (
    select 1 from public.portal_messages m
    join public.portal_conversations c on c.id = m.conversation_id
    where m.id = message_id
      and (is_parent_of_student(c.student_id) or can_access_school(c.school_id))
  )
);

drop policy if exists portal_message_attachments_insert on public.portal_message_attachments;
create policy portal_message_attachments_insert on public.portal_message_attachments
for insert to authenticated with check (
  exists (
    select 1 from public.portal_messages m
    join public.portal_conversations c on c.id = m.conversation_id
    where m.id = message_id
      and (is_parent_of_student(c.student_id) or can_access_school(c.school_id))
  )
);

-- Family notifications
drop policy if exists portal_family_notifications_select on public.portal_family_notifications;
create policy portal_family_notifications_select on public.portal_family_notifications
for select to authenticated using (user_id = auth.uid() or can_access_school(
  (select s.school_id from public.students s where s.id = student_id limit 1)
));

drop policy if exists portal_family_notifications_insert on public.portal_family_notifications;
create policy portal_family_notifications_insert on public.portal_family_notifications
for insert to authenticated with check (can_access_school(
  coalesce(
    (select s.school_id from public.students s where s.id = student_id limit 1),
    (select f.school_id from public.families f where f.id = family_id limit 1)
  )
) or user_id = auth.uid());

drop policy if exists portal_family_notifications_update on public.portal_family_notifications;
create policy portal_family_notifications_update on public.portal_family_notifications
for update to authenticated using (user_id = auth.uid());

-- Form templates: parents read active; staff manage
drop policy if exists portal_form_templates_select on public.portal_form_templates;
create policy portal_form_templates_select on public.portal_form_templates
for select to authenticated using (is_active and (can_access_school(school_id) or has_permission('portal.forms.submit')));

drop policy if exists portal_form_templates_write on public.portal_form_templates;
create policy portal_form_templates_write on public.portal_form_templates
for all to authenticated using (can_access_school(school_id)) with check (can_access_school(school_id));

-- Form submissions
drop policy if exists portal_form_submissions_select on public.portal_form_submissions;
create policy portal_form_submissions_select on public.portal_form_submissions
for select to authenticated using (
  submitted_by_user_id = auth.uid()
  or (student_id is not null and is_parent_of_student(student_id))
  or (family_id is not null and is_guardian_of_family(family_id))
  or exists (
    select 1 from public.portal_form_templates t
    where t.id = template_id and can_access_school(t.school_id)
  )
);

drop policy if exists portal_form_submissions_insert on public.portal_form_submissions;
create policy portal_form_submissions_insert on public.portal_form_submissions
for insert to authenticated with check (
  has_permission('portal.forms.submit')
  and (
    student_id is null or is_parent_of_student(student_id)
  )
  and (
    family_id is null or is_guardian_of_family(family_id)
  )
);

-- Conference requests
drop policy if exists portal_conference_requests_select on public.portal_conference_requests;
create policy portal_conference_requests_select on public.portal_conference_requests
for select to authenticated using (
  is_parent_of_student(student_id) or can_access_school(school_id)
);

drop policy if exists portal_conference_requests_insert on public.portal_conference_requests;
create policy portal_conference_requests_insert on public.portal_conference_requests
for insert to authenticated with check (
  is_parent_of_student(student_id) and has_permission('portal.conferences')
);

drop policy if exists portal_conference_requests_update on public.portal_conference_requests;
create policy portal_conference_requests_update on public.portal_conference_requests
for update to authenticated using (
  is_parent_of_student(student_id) or can_access_school(school_id)
);

-- Parent-visible meetings (extend read for parents)
drop policy if exists instructional_meetings_parent_select on public.student_instructional_meetings;
create policy instructional_meetings_parent_select on public.student_instructional_meetings
for select to authenticated using (
  parent_visible = true and is_parent_of_student(student_id)
);

-- Calendar export tokens
drop policy if exists portal_calendar_tokens_own on public.portal_calendar_export_tokens;
create policy portal_calendar_tokens_own on public.portal_calendar_export_tokens
for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

grant select, insert, update on public.portal_conversations to authenticated;
grant select, insert on public.portal_messages to authenticated;
grant select, insert, update on public.portal_message_reads to authenticated;
grant select, insert on public.portal_message_attachments to authenticated;
grant select, insert, update on public.portal_family_notifications to authenticated;
grant select on public.portal_form_templates to authenticated;
grant select, insert on public.portal_form_submissions to authenticated;
grant select, insert, update on public.portal_conference_requests to authenticated;
grant select, insert, delete on public.portal_calendar_export_tokens to authenticated;

-- Parent read policies for enrolled-family portal (FERPA-scoped via is_parent_of_student)
drop policy if exists student_growth_goals_parent_select on public.student_growth_goals;
create policy student_growth_goals_parent_select on public.student_growth_goals
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists student_learning_artifacts_parent_select on public.student_learning_artifacts;
create policy student_learning_artifacts_parent_select on public.student_learning_artifacts
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists ssis_academic_observations_parent_select on public.ssis_academic_observations;
create policy ssis_academic_observations_parent_select on public.ssis_academic_observations
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists ssis_funding_records_parent_select on public.ssis_student_funding_records;
create policy ssis_funding_records_parent_select on public.ssis_student_funding_records
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists ssis_medical_alerts_parent_select on public.ssis_medical_expiry_alerts;
create policy ssis_medical_alerts_parent_select on public.ssis_medical_expiry_alerts
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists student_enrollments_parent_select on public.student_enrollments;
create policy student_enrollments_parent_select on public.student_enrollments
  for select to authenticated using (is_parent_of_student(student_id));

drop policy if exists student_service_sessions_parent_select on public.student_service_sessions;
create policy student_service_sessions_parent_select on public.student_service_sessions
  for select to authenticated using (is_parent_of_student(student_id));
-- <<< END SOURCE 091_release7_parent_student_experience_rls.sql

-- >>> BEGIN SOURCE 092_release8_workforce_management_foundation.sql (blob 53b27f00b226ac628b511fb2a4a8cb9bcee61ef5)
-- =========================================
-- RELEASE 8: HUMAN CAPITAL & WORKFORCE MANAGEMENT
-- Extends Phase 1 HR — idempotent
-- =========================================

-- ---------------------------------------------------------------------------
-- 1. Employee profile extensions
-- ---------------------------------------------------------------------------

alter table public.employees
  add column if not exists supervisor_employee_id uuid references public.employees(id) on delete set null;

alter table public.employees
  add column if not exists separation_date date;

alter table public.employees
  add column if not exists department text;

alter table public.employees
  add column if not exists program text;

alter table public.employee_profiles
  add column if not exists emergency_contact_name text;

alter table public.employee_profiles
  add column if not exists emergency_contact_phone text;

alter table public.employee_certifications
  add column if not exists certification_type text
    check (certification_type is null or certification_type in (
      'teaching_license', 'therapy_license', 'cpr', 'first_aid', 'background_check',
      'fingerprint', 'professional', 'continuing_education', 'other'
    ));

create table if not exists public.employee_service_history (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  event_type text not null check (event_type in (
    'hire', 'promotion', 'transfer', 'leave', 'return', 'separation', 'other'
  )),
  title text not null,
  description text,
  effective_date date not null,
  recorded_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists idx_employee_service_history_employee
  on public.employee_service_history(employee_id, effective_date desc);

-- ---------------------------------------------------------------------------
-- 2. Recruiting & applicant tracking
-- ---------------------------------------------------------------------------

create table if not exists public.hr_job_postings (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  title text not null,
  department text,
  program text,
  employment_type text not null default 'full_time',
  description text,
  requirements text,
  status text not null default 'open'
    check (status in ('draft', 'open', 'closed', 'filled')),
  posted_at timestamptz,
  closes_at timestamptz,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists hr_job_postings_set_updated_at on public.hr_job_postings;
create trigger hr_job_postings_set_updated_at
  before update on public.hr_job_postings
  for each row execute function public.trigger_set_updated_at();

create table if not exists public.hr_job_applications (
  id uuid primary key default gen_random_uuid(),
  job_posting_id uuid not null references public.hr_job_postings(id) on delete cascade,
  candidate_name text not null,
  candidate_email text not null,
  candidate_phone text,
  resume_path text,
  pipeline_stage text not null default 'applied'
    check (pipeline_stage in (
      'applied', 'screening', 'interview', 'reference_check', 'background_check',
      'offer', 'hired', 'rejected', 'withdrawn'
    )),
  offer_letter_path text,
  background_check_status text default 'pending'
    check (background_check_status is null or background_check_status in ('pending', 'in_progress', 'cleared', 'failed')),
  reference_check_status text default 'pending'
    check (reference_check_status is null or reference_check_status in ('pending', 'in_progress', 'completed', 'failed')),
  notes text,
  hired_employee_id uuid references public.employees(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_hr_job_applications_posting on public.hr_job_applications(job_posting_id, pipeline_stage);

drop trigger if exists hr_job_applications_set_updated_at on public.hr_job_applications;
create trigger hr_job_applications_set_updated_at
  before update on public.hr_job_applications
  for each row execute function public.trigger_set_updated_at();

create table if not exists public.hr_candidate_interviews (
  id uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.hr_job_applications(id) on delete cascade,
  scheduled_at timestamptz not null,
  interview_type text not null default 'general',
  location_or_link text,
  interviewer_user_id uuid references public.users(id) on delete set null,
  status text not null default 'scheduled'
    check (status in ('scheduled', 'completed', 'cancelled', 'no_show')),
  notes text,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 3. Onboarding
-- ---------------------------------------------------------------------------

create table if not exists public.hr_onboarding_tasks (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  task_key text not null,
  title text not null,
  category text not null default 'general'
    check (category in ('paperwork', 'policy', 'technology', 'training', 'credential', 'equipment', 'other')),
  requires_signature boolean not null default false,
  signature_id uuid references public.platform_digital_signatures(id) on delete set null,
  status text not null default 'pending'
    check (status in ('pending', 'in_progress', 'completed', 'waived')),
  due_date date,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists idx_hr_onboarding_tasks_employee on public.hr_onboarding_tasks(employee_id, status);

-- ---------------------------------------------------------------------------
-- 4. Time & attendance
-- ---------------------------------------------------------------------------

create table if not exists public.employee_time_entries (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete cascade,
  entry_date date not null,
  clock_in timestamptz,
  clock_out timestamptz,
  hours_worked numeric(6, 2) check (hours_worked is null or hours_worked >= 0),
  entry_type text not null default 'regular'
    check (entry_type in ('regular', 'overtime', 'holiday', 'exception')),
  notes text,
  approved_by uuid references public.users(id) on delete set null,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected')),
  created_at timestamptz not null default now()
);

create index if not exists idx_employee_time_entries_employee on public.employee_time_entries(employee_id, entry_date desc);

create table if not exists public.leave_requests (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete cascade,
  leave_type text not null
    check (leave_type in ('pto', 'sick', 'personal', 'bereavement', 'fmla', 'unpaid', 'other')),
  start_date date not null,
  end_date date not null,
  hours_requested numeric(6, 2),
  reason text,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'denied', 'cancelled')),
  approved_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_leave_requests_employee on public.leave_requests(employee_id, status);

drop trigger if exists leave_requests_set_updated_at on public.leave_requests;
create trigger leave_requests_set_updated_at
  before update on public.leave_requests
  for each row execute function public.trigger_set_updated_at();

-- ---------------------------------------------------------------------------
-- 5. Performance management
-- ---------------------------------------------------------------------------

create table if not exists public.performance_evaluations (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete cascade,
  evaluation_type text not null default 'annual'
    check (evaluation_type in ('annual', 'mid_year', 'probationary', 'improvement', 'informal')),
  evaluation_period_start date,
  evaluation_period_end date,
  overall_rating text,
  summary text,
  coaching_notes text,
  status text not null default 'draft'
    check (status in ('draft', 'submitted', 'acknowledged', 'completed')),
  evaluator_user_id uuid references public.users(id) on delete set null,
  employee_acknowledged_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.performance_goals (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  evaluation_id uuid references public.performance_evaluations(id) on delete set null,
  title text not null,
  description text,
  target_date date,
  status text not null default 'active'
    check (status in ('active', 'completed', 'cancelled')),
  progress_notes text,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 6. Professional development
-- ---------------------------------------------------------------------------

create table if not exists public.pd_courses (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  title text not null,
  description text,
  is_required boolean not null default false,
  ceu_credits numeric(4, 2) default 0,
  delivery_mode text default 'online'
    check (delivery_mode is null or delivery_mode in ('online', 'in_person', 'hybrid')),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.employee_training_records (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  course_id uuid references public.pd_courses(id) on delete set null,
  course_title text not null,
  completed_at timestamptz,
  certificate_path text,
  ceu_earned numeric(4, 2) default 0,
  status text not null default 'assigned'
    check (status in ('assigned', 'in_progress', 'completed', 'expired')),
  created_at timestamptz not null default now()
);

create index if not exists idx_employee_training_records_employee on public.employee_training_records(employee_id);

-- ---------------------------------------------------------------------------
-- 7. Substitute & volunteer management
-- ---------------------------------------------------------------------------

create table if not exists public.substitute_pool_members (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid references public.employees(id) on delete set null,
  school_id uuid not null references public.schools(id) on delete cascade,
  substitute_name text not null,
  contact_email text,
  contact_phone text,
  credentials_verified boolean not null default false,
  availability_notes text,
  status text not null default 'active'
    check (status in ('active', 'inactive', 'suspended')),
  created_at timestamptz not null default now()
);

create table if not exists public.substitute_assignments (
  id uuid primary key default gen_random_uuid(),
  substitute_id uuid not null references public.substitute_pool_members(id) on delete cascade,
  instructional_session_id uuid references public.instructional_sessions(id) on delete set null,
  assigned_at timestamptz not null default now(),
  status text not null default 'requested'
    check (status in ('requested', 'confirmed', 'completed', 'cancelled')),
  lesson_plan_notes text,
  performance_notes text,
  hours_worked numeric(6, 2),
  created_at timestamptz not null default now()
);

create table if not exists public.volunteers (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  first_name text not null,
  last_name text not null,
  contact_email text,
  contact_phone text,
  emergency_contact_name text,
  emergency_contact_phone text,
  background_check_status text not null default 'pending'
    check (background_check_status in ('pending', 'cleared', 'failed', 'expired')),
  training_completed boolean not null default false,
  status text not null default 'active'
    check (status in ('active', 'inactive')),
  created_at timestamptz not null default now()
);

create table if not exists public.volunteer_hours (
  id uuid primary key default gen_random_uuid(),
  volunteer_id uuid not null references public.volunteers(id) on delete cascade,
  assignment_description text not null,
  served_at date not null,
  hours_served numeric(5, 2) not null check (hours_served > 0),
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 8. Employee document vault
-- ---------------------------------------------------------------------------

create table if not exists public.employee_documents (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees(id) on delete cascade,
  document_type text not null
    check (document_type in (
      'contract', 'license', 'certification', 'performance_review', 'training',
      'payroll_form', 'benefits', 'disciplinary', 'policy_acknowledgement', 'other'
    )),
  file_name text not null,
  storage_path text not null,
  version_number integer not null default 1,
  signature_id uuid references public.platform_digital_signatures(id) on delete set null,
  uploaded_by uuid references public.users(id) on delete set null,
  expires_at date,
  created_at timestamptz not null default now()
);

create index if not exists idx_employee_documents_employee on public.employee_documents(employee_id, document_type);

-- ---------------------------------------------------------------------------
-- 9. Permissions
-- ---------------------------------------------------------------------------

insert into public.platform_permissions (permission_key, name, description, module, category, sort_order)
values
  ('hr.recruiting', 'HR Recruiting', 'Manage job postings and applicant tracking', 'hr', 'workforce', 220),
  ('hr.compliance', 'HR Compliance', 'Monitor licenses, training, and compliance', 'hr', 'workforce', 221),
  ('hr.analytics', 'HR Analytics', 'View workforce analytics dashboards', 'hr', 'workforce', 222),
  ('employee.self_service', 'Employee Self-Service', 'Access employee portal features', 'hr', 'workforce', 223)
on conflict (permission_key) do nothing;

insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name = 'HR' and p.permission_key in ('hr.recruiting', 'hr.compliance', 'hr.analytics')
on conflict do nothing;

insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name in ('TEACHER', 'THERAPIST', 'SUPPORT_STAFF', 'SCHOOL_LEADER', 'FINANCE', 'HR')
  and p.permission_key = 'employee.self_service'
on conflict do nothing;

-- Seed default onboarding tasks template function via insert on hire (app layer)
-- <<< END SOURCE 092_release8_workforce_management_foundation.sql

-- >>> BEGIN SOURCE 093_release8_workforce_management_rls.sql (blob 9f0f092a70f9396c567e137cdbcd080b40b4a131)
-- =========================================
-- RELEASE 8 RLS: Workforce Management
-- =========================================

alter table public.employee_service_history enable row level security;
alter table public.hr_job_postings enable row level security;
alter table public.hr_job_applications enable row level security;
alter table public.hr_candidate_interviews enable row level security;
alter table public.hr_onboarding_tasks enable row level security;
alter table public.employee_time_entries enable row level security;
alter table public.leave_requests enable row level security;
alter table public.performance_evaluations enable row level security;
alter table public.performance_goals enable row level security;
alter table public.pd_courses enable row level security;
alter table public.employee_training_records enable row level security;
alter table public.substitute_pool_members enable row level security;
alter table public.substitute_assignments enable row level security;
alter table public.volunteers enable row level security;
alter table public.volunteer_hours enable row level security;
alter table public.employee_documents enable row level security;

-- Service history
drop policy if exists employee_service_history_access on public.employee_service_history;
create policy employee_service_history_access on public.employee_service_history
  for all to authenticated using (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  ) with check (can_access_school((select school_id from public.employees e where e.id = employee_id)));

-- Recruiting
drop policy if exists hr_job_postings_access on public.hr_job_postings;
create policy hr_job_postings_access on public.hr_job_postings
  for all to authenticated using (can_access_school(school_id)) with check (can_access_school(school_id));

drop policy if exists hr_job_applications_access on public.hr_job_applications;
create policy hr_job_applications_access on public.hr_job_applications
  for all to authenticated using (
    exists (select 1 from public.hr_job_postings jp where jp.id = job_posting_id and can_access_school(jp.school_id))
  );

drop policy if exists hr_candidate_interviews_access on public.hr_candidate_interviews;
create policy hr_candidate_interviews_access on public.hr_candidate_interviews
  for all to authenticated using (
    exists (
      select 1 from public.hr_job_applications ja
      join public.hr_job_postings jp on jp.id = ja.job_posting_id
      where ja.id = application_id and can_access_school(jp.school_id)
    )
  );

-- Onboarding
drop policy if exists hr_onboarding_tasks_access on public.hr_onboarding_tasks;
create policy hr_onboarding_tasks_access on public.hr_onboarding_tasks
  for all to authenticated using (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  ) with check (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  );

-- Time & leave
drop policy if exists employee_time_entries_access on public.employee_time_entries;
create policy employee_time_entries_access on public.employee_time_entries
  for all to authenticated using (can_access_school(school_id) or is_self_employee(employee_id))
  with check (can_access_school(school_id) or is_self_employee(employee_id));

drop policy if exists leave_requests_access on public.leave_requests;
create policy leave_requests_access on public.leave_requests
  for all to authenticated using (can_access_school(school_id) or is_self_employee(employee_id))
  with check (can_access_school(school_id) or is_self_employee(employee_id));

-- Performance
drop policy if exists performance_evaluations_access on public.performance_evaluations;
create policy performance_evaluations_access on public.performance_evaluations
  for all to authenticated using (can_access_school(school_id) or is_self_employee(employee_id));

drop policy if exists performance_goals_access on public.performance_goals;
create policy performance_goals_access on public.performance_goals
  for all to authenticated using (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  );

-- PD
drop policy if exists pd_courses_access on public.pd_courses;
create policy pd_courses_access on public.pd_courses
  for select to authenticated using (school_id is null or can_access_school(school_id) or has_permission('employee.self_service'));

drop policy if exists pd_courses_write on public.pd_courses;
create policy pd_courses_write on public.pd_courses
  for all to authenticated using (school_id is null or can_access_school(school_id))
  with check (school_id is null or can_access_school(school_id));

drop policy if exists employee_training_records_access on public.employee_training_records;
create policy employee_training_records_access on public.employee_training_records
  for all to authenticated using (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  );

-- Substitutes & volunteers
drop policy if exists substitute_pool_access on public.substitute_pool_members;
create policy substitute_pool_access on public.substitute_pool_members
  for all to authenticated using (can_access_school(school_id));

drop policy if exists substitute_assignments_access on public.substitute_assignments;
create policy substitute_assignments_access on public.substitute_assignments
  for all to authenticated using (
    exists (select 1 from public.substitute_pool_members sp where sp.id = substitute_id and can_access_school(sp.school_id))
  );

drop policy if exists volunteers_access on public.volunteers;
create policy volunteers_access on public.volunteers
  for all to authenticated using (can_access_school(school_id));

drop policy if exists volunteer_hours_access on public.volunteer_hours;
create policy volunteer_hours_access on public.volunteer_hours
  for all to authenticated using (
    exists (select 1 from public.volunteers v where v.id = volunteer_id and can_access_school(v.school_id))
  );

-- Document vault
drop policy if exists employee_documents_access on public.employee_documents;
create policy employee_documents_access on public.employee_documents
  for all to authenticated using (
    can_access_school((select school_id from public.employees e where e.id = employee_id))
    or is_self_employee(employee_id)
  ) with check (can_access_school((select school_id from public.employees e where e.id = employee_id)));

grant select, insert, update, delete on public.employee_service_history to authenticated;
grant select, insert, update, delete on public.hr_job_postings to authenticated;
grant select, insert, update, delete on public.hr_job_applications to authenticated;
grant select, insert, update, delete on public.hr_candidate_interviews to authenticated;
grant select, insert, update, delete on public.hr_onboarding_tasks to authenticated;
grant select, insert, update, delete on public.employee_time_entries to authenticated;
grant select, insert, update, delete on public.leave_requests to authenticated;
grant select, insert, update, delete on public.performance_evaluations to authenticated;
grant select, insert, update, delete on public.performance_goals to authenticated;
grant select, insert, update, delete on public.pd_courses to authenticated;
grant select, insert, update, delete on public.employee_training_records to authenticated;
grant select, insert, update, delete on public.substitute_pool_members to authenticated;
grant select, insert, update, delete on public.substitute_assignments to authenticated;
grant select, insert, update, delete on public.volunteers to authenticated;
grant select, insert, update, delete on public.volunteer_hours to authenticated;
grant select, insert, update, delete on public.employee_documents to authenticated;
-- <<< END SOURCE 093_release8_workforce_management_rls.sql

-- >>> BEGIN SOURCE 094_release9_executive_intelligence_foundation.sql (blob ce81a96cbcef1ce22118520b43e4aecbcd8fa9c2)
-- =========================================
-- RELEASE 9: EXECUTIVE INTELLIGENCE & DECISION SUPPORT
-- Reporting layer + executive workspace — idempotent
-- Does NOT duplicate operational data
-- =========================================

-- ---------------------------------------------------------------------------
-- 1. KPI definitions & historical snapshots
-- ---------------------------------------------------------------------------

create table if not exists public.executive_kpi_definitions (
  id uuid primary key default gen_random_uuid(),
  kpi_key text not null unique,
  display_name text not null,
  category text not null default 'general'
    check (category in (
      'enrollment', 'retention', 'academic', 'attendance', 'engagement',
      'financial', 'workforce', 'compliance', 'grants', 'strategic'
    )),
  unit text not null default 'number'
    check (unit in ('number', 'percent', 'currency', 'ratio', 'days')),
  target_value numeric(14, 4),
  warning_threshold numeric(14, 4),
  critical_threshold numeric(14, 4),
  higher_is_better boolean not null default true,
  data_source text not null default 'computed',
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.executive_kpi_snapshots (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  campus_id uuid references public.campuses(id) on delete set null,
  program text,
  kpi_key text not null references public.executive_kpi_definitions(kpi_key) on delete cascade,
  snapshot_date date not null,
  actual_value numeric(14, 4) not null,
  target_value numeric(14, 4),
  prior_period_value numeric(14, 4),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (school_id, campus_id, program, kpi_key, snapshot_date)
);

create index if not exists idx_executive_kpi_snapshots_lookup
  on public.executive_kpi_snapshots(school_id, kpi_key, snapshot_date desc);

-- ---------------------------------------------------------------------------
-- 2. Customizable executive dashboard layouts
-- ---------------------------------------------------------------------------

create table if not exists public.executive_dashboard_layouts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  layout_name text not null default 'default',
  role_scope text,
  widgets jsonb not null default '[]'::jsonb,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, layout_name)
);

drop trigger if exists executive_dashboard_layouts_set_updated_at on public.executive_dashboard_layouts;
create trigger executive_dashboard_layouts_set_updated_at
  before update on public.executive_dashboard_layouts
  for each row execute function public.trigger_set_updated_at();

-- ---------------------------------------------------------------------------
-- 3. Alert & insight engine
-- ---------------------------------------------------------------------------

create table if not exists public.executive_insights (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  insight_type text not null
    check (insight_type in (
      'trend', 'threshold', 'forecast', 'risk', 'benchmark', 'recommendation'
    )),
  severity text not null default 'info'
    check (severity in ('info', 'normal', 'warning', 'critical')),
  title text not null,
  body text not null,
  metric_key text,
  metric_value numeric(14, 4),
  comparison_value numeric(14, 4),
  recommended_action text,
  href text,
  entity_type text,
  entity_id uuid,
  is_dismissed boolean not null default false,
  dismissed_by uuid references public.users(id) on delete set null,
  dismissed_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now()
);

