  (null, 'new_school_opening', 'New School Opening', 'Launch a new school location', 'capital_project', 'operations', true, 365)
on conflict (school_id, playbook_key) do nothing;

insert into public.work_playbook_steps (playbook_id, step_order, title, task_type, offset_days, default_priority, requires_approval, creates_compliance)
select pb.id, s.step_order, s.title, s.task_type, s.offset_days, s.default_priority, s.requires_approval, s.creates_compliance
from public.work_playbooks pb
cross join lateral (values
  ('new_student_enrollment', 1, 'Collect enrollment documents', 'document', 0, 'high', false, false),
  ('new_student_enrollment', 2, 'Verify immunization records', 'compliance', 3, 'high', false, true),
  ('new_student_enrollment', 3, 'Schedule orientation meeting', 'meeting', 7, 'normal', false, false),
  ('new_student_enrollment', 4, 'Complete tuition setup', 'task', 10, 'normal', false, false),
  ('teacher_hiring', 1, 'Post job opening', 'task', 0, 'normal', false, false),
  ('teacher_hiring', 2, 'Screen candidates', 'task', 7, 'normal', false, false),
  ('teacher_hiring', 3, 'Conduct interviews', 'meeting', 14, 'high', false, false),
  ('teacher_hiring', 4, 'Extend offer', 'approval', 21, 'high', true, false),
  ('iep_annual_review', 1, 'Schedule IEP meeting', 'meeting', 0, 'high', false, false),
  ('iep_annual_review', 2, 'Collect progress data', 'task', 7, 'high', false, false),
  ('iep_annual_review', 3, 'Draft IEP document', 'document', 14, 'critical', false, true),
  ('iep_annual_review', 4, 'Obtain parent signatures', 'approval', 21, 'high', true, false)
) as s(playbook_key, step_order, title, task_type, offset_days, default_priority, requires_approval, creates_compliance)
where pb.playbook_key = s.playbook_key
  and not exists (
    select 1 from public.work_playbook_steps existing where existing.playbook_id = pb.id
  );
-- <<< END SOURCE 100_release102_work_management_foundation.sql

-- >>> BEGIN SOURCE 101_release102_work_management_rls.sql (blob ac9dc7ccddc171d3f1fdbe65dfc6e4c76358d0b8)
-- =========================================
-- RELEASE 10.2 RLS: Enterprise Work Management
-- =========================================

alter table public.work_playbooks enable row level security;
alter table public.work_playbook_steps enable row level security;
alter table public.work_playbook_runs enable row level security;
alter table public.work_projects enable row level security;
alter table public.work_milestones enable row level security;
alter table public.work_tasks enable row level security;
alter table public.work_task_assignees enable row level security;
alter table public.work_task_dependencies enable row level security;
alter table public.work_task_checklists enable row level security;
alter table public.work_checklist_items enable row level security;
alter table public.work_task_comments enable row level security;
alter table public.work_task_attachments enable row level security;
alter table public.work_activity_log enable row level security;
alter table public.work_time_entries enable row level security;
alter table public.work_project_risks enable row level security;
alter table public.work_status_history enable row level security;

-- Playbooks
drop policy if exists work_playbooks_read on public.work_playbooks;
create policy work_playbooks_read on public.work_playbooks
  for select to authenticated
  using (
    has_permission('work.view') or has_permission('work.manage') or has_permission('work.admin')
    or (school_id is null or can_access_school(school_id))
  );

drop policy if exists work_playbooks_manage on public.work_playbooks;
create policy work_playbooks_manage on public.work_playbooks
  for all to authenticated
  using (
    has_permission('work.admin')
    or (has_permission('work.manage') and (school_id is null or can_access_school(school_id)))
  )
  with check (
    has_permission('work.admin')
    or (has_permission('work.manage') and (school_id is null or can_access_school(school_id)))
  );

drop policy if exists work_playbook_steps_access on public.work_playbook_steps;
create policy work_playbook_steps_access on public.work_playbook_steps
  for all to authenticated
  using (
    exists (
      select 1 from public.work_playbooks pb
      where pb.id = playbook_id
        and (has_permission('work.view') or has_permission('work.manage') or has_permission('work.admin'))
    )
  )
  with check (has_permission('work.admin') or has_permission('work.manage'));

drop policy if exists work_playbook_runs_access on public.work_playbook_runs;
create policy work_playbook_runs_access on public.work_playbook_runs
  for all to authenticated
  using (
    has_permission('work.view') or has_permission('work.manage')
    or started_by = auth.uid()
    or (school_id is null or can_access_school(school_id))
  )
  with check (has_permission('work.manage') or started_by = auth.uid());

-- Projects
drop policy if exists work_projects_access on public.work_projects;
create policy work_projects_access on public.work_projects
  for all to authenticated
  using (
    (
      (school_id is null or can_access_school(school_id))
      and (has_permission('work.view') or has_permission('work.manage') or has_permission('work.executive'))
    )
    or owner_user_id = auth.uid()
    or created_by = auth.uid()
    or exists (
      select 1 from public.work_tasks t
      where t.project_id = work_projects.id
        and (t.owner_user_id = auth.uid() or exists (
          select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()
        ))
    )
  )
  with check (
    (school_id is null or can_access_school(school_id))
    and (has_permission('work.manage') or owner_user_id = auth.uid() or created_by = auth.uid())
  );

-- Milestones
drop policy if exists work_milestones_access on public.work_milestones;
create policy work_milestones_access on public.work_milestones
  for all to authenticated
  using (
    exists (
      select 1 from public.work_projects p
      where p.id = project_id
        and (
          (p.school_id is null or can_access_school(p.school_id))
          and (has_permission('work.view') or has_permission('work.manage'))
          or p.owner_user_id = auth.uid()
        )
    )
  )
  with check (
    exists (
      select 1 from public.work_projects p
      where p.id = project_id
        and (has_permission('work.manage') or p.owner_user_id = auth.uid())
    )
  );

-- Tasks
drop policy if exists work_tasks_access on public.work_tasks;
create policy work_tasks_access on public.work_tasks
  for all to authenticated
  using (
    (
      (school_id is null or can_access_school(school_id))
      and (has_permission('work.view') or has_permission('work.manage'))
    )
    or owner_user_id = auth.uid()
    or created_by = auth.uid()
    or exists (select 1 from public.work_task_assignees a where a.task_id = work_tasks.id and a.user_id = auth.uid())
    or (student_id is not null and is_parent_of_student(student_id))
    or (student_id is not null and exists (select 1 from public.students s where s.id = student_id and s.user_id = auth.uid()))
    or (employee_id is not null and is_self_employee(employee_id))
  )
  with check (
    (
      (school_id is null or can_access_school(school_id))
      and (has_permission('work.manage') or owner_user_id = auth.uid() or created_by = auth.uid())
    )
    or owner_user_id = auth.uid()
    or exists (select 1 from public.work_task_assignees a where a.task_id = work_tasks.id and a.user_id = auth.uid() and a.role in ('assignee','reviewer'))
    or (employee_id is not null and is_self_employee(employee_id))
  );

drop policy if exists work_task_assignees_access on public.work_task_assignees;
create policy work_task_assignees_access on public.work_task_assignees
  for all to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1 from public.work_tasks t
      where t.id = task_id
        and (has_permission('work.view') or t.owner_user_id = auth.uid())
    )
  )
  with check (
    has_permission('work.manage')
    or exists (select 1 from public.work_tasks t where t.id = task_id and t.owner_user_id = auth.uid())
  );

drop policy if exists work_task_dependencies_access on public.work_task_dependencies;
create policy work_task_dependencies_access on public.work_task_dependencies
  for all to authenticated
  using (has_permission('work.view') or has_permission('work.manage'))
  with check (has_permission('work.manage'));

drop policy if exists work_task_checklists_access on public.work_task_checklists;
create policy work_task_checklists_access on public.work_task_checklists
  for all to authenticated
  using (
    exists (
      select 1 from public.work_tasks t
      where t.id = task_id
        and (has_permission('work.view') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  )
  with check (
    exists (
      select 1 from public.work_tasks t
      where t.id = task_id
        and (has_permission('work.manage') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  );

drop policy if exists work_checklist_items_access on public.work_checklist_items;
create policy work_checklist_items_access on public.work_checklist_items
  for all to authenticated
  using (
    exists (
      select 1 from public.work_task_checklists c
      join public.work_tasks t on t.id = c.task_id
      where c.id = checklist_id
        and (has_permission('work.view') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  )
  with check (
    exists (
      select 1 from public.work_task_checklists c
      join public.work_tasks t on t.id = c.task_id
      where c.id = checklist_id
        and (has_permission('work.manage') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  );

drop policy if exists work_task_comments_access on public.work_task_comments;
create policy work_task_comments_access on public.work_task_comments
  for all to authenticated
  using (
    exists (
      select 1 from public.work_tasks t
      where t.id = task_id
        and (has_permission('work.view') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  )
  with check (
    author_user_id = auth.uid() or has_permission('work.manage')
  );

drop policy if exists work_task_attachments_access on public.work_task_attachments;
create policy work_task_attachments_access on public.work_task_attachments
  for all to authenticated
  using (
    exists (
      select 1 from public.work_tasks t
      where t.id = task_id
        and (has_permission('work.view') or t.owner_user_id = auth.uid()
          or exists (select 1 from public.work_task_assignees a where a.task_id = t.id and a.user_id = auth.uid()))
    )
  )
  with check (uploaded_by = auth.uid() or has_permission('work.manage'));

drop policy if exists work_activity_log_read on public.work_activity_log;
create policy work_activity_log_read on public.work_activity_log
  for select to authenticated
  using (has_permission('work.view') or has_permission('work.manage') or actor_user_id = auth.uid());

drop policy if exists work_activity_log_write on public.work_activity_log;
create policy work_activity_log_write on public.work_activity_log
  for insert to authenticated
  with check (has_permission('work.manage') or actor_user_id = auth.uid());

drop policy if exists work_time_entries_access on public.work_time_entries;
create policy work_time_entries_access on public.work_time_entries
  for all to authenticated
  using (user_id = auth.uid() or has_permission('work.view') or has_permission('work.manage'))
  with check (user_id = auth.uid() or has_permission('work.manage'));

drop policy if exists work_project_risks_access on public.work_project_risks;
create policy work_project_risks_access on public.work_project_risks
  for all to authenticated
  using (
    exists (
      select 1 from public.work_projects p
      where p.id = project_id
        and (has_permission('work.view') or has_permission('work.executive') or p.owner_user_id = auth.uid())
    )
  )
  with check (has_permission('work.manage') or owner_user_id = auth.uid());

drop policy if exists work_status_history_read on public.work_status_history;
create policy work_status_history_read on public.work_status_history
  for select to authenticated
  using (has_permission('work.view') or has_permission('work.manage'));

drop policy if exists work_status_history_write on public.work_status_history;
create policy work_status_history_write on public.work_status_history
  for insert to authenticated
  with check (has_permission('work.manage') or changed_by = auth.uid());

grant select, insert, update, delete on public.work_playbooks to authenticated;
grant select, insert, update, delete on public.work_playbook_steps to authenticated;
grant select, insert, update, delete on public.work_playbook_runs to authenticated;
grant select, insert, update, delete on public.work_projects to authenticated;
grant select, insert, update, delete on public.work_milestones to authenticated;
grant select, insert, update, delete on public.work_tasks to authenticated;
grant select, insert, update, delete on public.work_task_assignees to authenticated;
grant select, insert, update, delete on public.work_task_dependencies to authenticated;
grant select, insert, update, delete on public.work_task_checklists to authenticated;
grant select, insert, update, delete on public.work_checklist_items to authenticated;
grant select, insert, update, delete on public.work_task_comments to authenticated;
grant select, insert, update, delete on public.work_task_attachments to authenticated;
grant select, insert on public.work_activity_log to authenticated;
grant select, insert, update, delete on public.work_time_entries to authenticated;
grant select, insert, update, delete on public.work_project_risks to authenticated;
grant select, insert on public.work_status_history to authenticated;
-- <<< END SOURCE 101_release102_work_management_rls.sql

-- >>> BEGIN SOURCE 102_release105_financial_intelligence_foundation.sql (blob ecfb9d4bf1541bb907ccd797d5140767d0128163)
-- =========================================
-- RELEASE 10.5: FINANCIAL INTELLIGENCE & BUSINESS ANALYTICS
-- BI layer — extends (does not replace) operational finance
-- =========================================

-- ---------------------------------------------------------------------------
-- 1. Cost allocation rules
-- ---------------------------------------------------------------------------

create table if not exists public.fi_allocation_rules (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  rule_key text not null,
  name text not null,
  category text not null
    check (category in (
      'payroll','benefits','payroll_tax','technology','curriculum','facility',
      'admin_overhead','marketing','insurance','utilities','occupancy','shared'
    )),
  allocation_method text not null default 'enrollment'
    check (allocation_method in ('enrollment','instructional_hours','revenue','square_feet','headcount','fixed')),
  allocation_pct numeric(8,4) not null default 0,
  fixed_amount numeric(14,2),
  is_active boolean not null default true,
  effective_from date not null default current_date,
  effective_to date,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (school_id, rule_key, effective_from)
);

-- ---------------------------------------------------------------------------
-- 2. Profitability snapshots (class, teacher, program, student, school, family)
-- ---------------------------------------------------------------------------

create table if not exists public.fi_profitability_snapshots (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  entity_type text not null
    check (entity_type in ('class','teacher','program','student','school','family','campus')),
  entity_id uuid,
  entity_key text,
  period_type text not null default 'monthly'
    check (period_type in ('weekly','monthly','quarterly','annual')),
  period_start date not null,
  period_end date not null,
  revenue numeric(14,2) not null default 0,
  total_cost numeric(14,2) not null default 0,
  gross_margin numeric(14,2) not null default 0,
  net_margin numeric(14,2) not null default 0,
  contribution_margin numeric(14,2) not null default 0,
  margin_pct numeric(8,4) not null default 0,
  ebitda_contribution numeric(14,2),
  health_indicator text not null default 'green'
    check (health_indicator in ('green','yellow','red')),
  enrollment_count integer,
  capacity integer,
  instructional_hours numeric(10,2),
  revenue_per_seat numeric(12,2),
  cost_per_seat numeric(12,2),
  profit_per_seat numeric(12,2),
  revenue_per_hour numeric(12,2),
  cost_per_hour numeric(12,2),
  profit_per_hour numeric(12,2),
  break_even_enrollment numeric(8,2),
  metrics jsonb not null default '{}'::jsonb,
  computed_at timestamptz not null default now(),
  unique (school_id, entity_type, entity_id, entity_key, period_type, period_start)
);

create index if not exists idx_fi_profitability_entity on public.fi_profitability_snapshots(entity_type, entity_id, period_start desc);
create index if not exists idx_fi_profitability_school on public.fi_profitability_snapshots(school_id, period_start desc);

-- ---------------------------------------------------------------------------
-- 3. Break-even analysis
-- ---------------------------------------------------------------------------

create table if not exists public.fi_break_even_snapshots (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  entity_type text not null check (entity_type in ('class','program','teacher','campus','school')),
  entity_id uuid,
  entity_key text,
  minimum_students numeric(8,2),
  optimal_students numeric(8,2),
  max_profitability_students numeric(8,2),
  current_enrollment integer,
  available_seats integer,
  unused_capacity_hours numeric(10,2),
  is_underperforming boolean not null default false,
  is_overstaffed boolean not null default false,
  snapshot_date date not null default current_date,
  metrics jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_fi_break_even_school on public.fi_break_even_snapshots(school_id, snapshot_date desc);

-- ---------------------------------------------------------------------------
-- 4. Scenario modeling
-- ---------------------------------------------------------------------------

create table if not exists public.fi_scenarios (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  name text not null,
  description text,
  scenario_type text not null default 'custom'
    check (scenario_type in (
      'tuition_increase','tuition_decrease','hire_teachers','add_classes','close_classes',
      'enrollment_increase','enrollment_decrease','scholarship_change','esa_change',
      'grant_change','salary_increase','facility_expansion','custom'
    )),
  baseline_period_start date,
  baseline_period_end date,
  inputs jsonb not null default '{}'::jsonb,
  status text not null default 'draft' check (status in ('draft','computed','archived')),
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.fi_scenario_results (
  id uuid primary key default gen_random_uuid(),
  scenario_id uuid not null references public.fi_scenarios(id) on delete cascade,
  projected_revenue numeric(14,2) not null default 0,
  projected_expenses numeric(14,2) not null default 0,
  projected_payroll numeric(14,2) not null default 0,
  projected_ebitda numeric(14,2) not null default 0,
  projected_cash_flow numeric(14,2) not null default 0,
  projected_margin_pct numeric(8,4) not null default 0,
  delta_revenue numeric(14,2) not null default 0,
  delta_ebitda numeric(14,2) not null default 0,
  outputs jsonb not null default '{}'::jsonb,
  computed_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 5. QuickBooks / external financial import (source tracking — no ops replacement)
-- ---------------------------------------------------------------------------

create table if not exists public.fi_import_batches (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  source_system text not null default 'quickbooks'
    check (source_system in ('quickbooks','csv','excel','iif','qbo_export','manual')),
  import_type text not null
    check (import_type in (
      'chart_of_accounts','general_ledger','journal_entries','profit_loss',
      'balance_sheet','cash_flow','budget','payroll_summary','vendors','customers',
      'classes','locations','transactions','historical'
    )),
  file_name text,
  file_format text,
  status text not null default 'pending'
    check (status in ('pending','processing','completed','failed','reconciled')),
  row_count integer not null default 0,
  error_message text,
  imported_by uuid references public.users(id) on delete set null,
  imported_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.fi_external_accounts (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  import_batch_id uuid references public.fi_import_batches(id) on delete set null,
  external_account_id text,
  account_number text,
  account_name text not null,
  account_type text,
  parent_account text,
  is_active boolean not null default true,
  source_system text not null default 'quickbooks',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.fi_external_transactions (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  import_batch_id uuid references public.fi_import_batches(id) on delete set null,
  external_transaction_id text,
  transaction_date date not null,
  account_name text,
  account_number text,
  debit_amount numeric(14,2) not null default 0,
  credit_amount numeric(14,2) not null default 0,
  amount numeric(14,2) not null default 0,
  description text,
  class_name text,
  location_name text,
  vendor_name text,
  customer_name text,
  source_system text not null default 'quickbooks',
  reconciliation_status text not null default 'unmatched'
    check (reconciliation_status in ('unmatched','matched','ignored')),
  matched_entity_type text,
  matched_entity_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_fi_external_txn_school on public.fi_external_transactions(school_id, transaction_date desc);
create index if not exists idx_fi_import_batches_school on public.fi_import_batches(school_id, imported_at desc);

-- ---------------------------------------------------------------------------
-- 6. Financial intelligence alerts
-- ---------------------------------------------------------------------------

create table if not exists public.fi_financial_alerts (
  id uuid primary key default gen_random_uuid(),
  school_id uuid references public.schools(id) on delete cascade,
  alert_type text not null
    check (alert_type in (
      'class_below_breakeven','program_loss','low_cash','declining_enrollment',
      'scholarship_overallocation','state_funding_discrepancy','payroll_spike',
      'budget_overrun','collection_issue','grant_compliance'
    )),
  severity text not null default 'normal' check (severity in ('low','normal','high','critical')),
  title text not null,
  body text,
  entity_type text,
  entity_id uuid,
  mission_control_item_id uuid,
  is_resolved boolean not null default false,
  resolved_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists idx_fi_alerts_school on public.fi_financial_alerts(school_id, is_resolved, created_at desc);

-- ---------------------------------------------------------------------------
-- 7. Triggers
-- ---------------------------------------------------------------------------

drop trigger if exists fi_scenarios_set_updated_at on public.fi_scenarios;
create trigger fi_scenarios_set_updated_at
  before update on public.fi_scenarios
  for each row execute function public.trigger_set_updated_at();

-- ---------------------------------------------------------------------------
-- 8. Reporting views
-- ---------------------------------------------------------------------------

create or replace view public.rpt_fi_class_profitability as
select
  p.school_id,
  p.entity_id as course_section_id,
  p.entity_key as section_code,
  p.period_type,
  p.period_start,
  p.revenue,
  p.total_cost,
  p.gross_margin,
  p.net_margin,
  p.margin_pct,
  p.health_indicator,
  p.enrollment_count,
  p.capacity,
  p.break_even_enrollment,
  p.revenue_per_seat,
  p.profit_per_seat,
  p.metrics
from public.fi_profitability_snapshots p
where p.entity_type = 'class';

create or replace view public.rpt_fi_program_profitability as
select
  p.school_id,
  p.entity_key as program,
  p.period_start,
  p.revenue,
  p.total_cost,
  p.net_margin,
  p.ebitda_contribution,
  p.margin_pct,
  p.health_indicator,
  p.enrollment_count,
  p.metrics
from public.fi_profitability_snapshots p
where p.entity_type = 'program';

create or replace view public.rpt_fi_school_summary as
select
  p.school_id,
  sch.name as school_name,
  p.period_start,
  p.revenue,
  p.total_cost,
  p.gross_margin,
  p.net_margin,
  p.ebitda_contribution,
  p.margin_pct,
  p.health_indicator,
  p.enrollment_count,
  p.metrics
from public.fi_profitability_snapshots p
left join public.schools sch on sch.id = p.school_id
where p.entity_type = 'school';

grant select on public.rpt_fi_class_profitability to authenticated;
grant select on public.rpt_fi_program_profitability to authenticated;
grant select on public.rpt_fi_school_summary to authenticated;

-- ---------------------------------------------------------------------------
-- 9. Permissions
-- ---------------------------------------------------------------------------

insert into public.platform_permissions (permission_key, name, description, module, category, sort_order)
