-- =========================================

insert into public.roles (name, display_name, description, is_system, sort_order)
values
  ('FOUNDER', 'Founder', 'Highest platform role with JAG and AcademyOS access.', true, 1),
  ('EXECUTIVE_DIRECTOR', 'Executive Director', 'Executive leadership across schools and AcademyOS modules.', true, 20),
  ('SCHOOL_LEADER', 'School Leader', 'School-level leadership for admissions, SIS, and reporting.', true, 50),
  ('ADMINISTRATOR', 'Administrator', 'Platform administration, users, roles, and system configuration.', true, 55),
  ('ADMISSIONS', 'Admissions', 'Admissions pipeline and enrollment operations.', true, 60),
  ('ACCOUNTING', 'Accounting', 'Accounting and financial operations access.', true, 70),
  ('HR', 'Human Resources', 'Workforce, recruiting, and HR operations.', true, 80),
  ('TEACHER', 'Teacher', 'Instructional staff with teacher workspace access.', true, 120),
  ('BOARD_MEMBER', 'Board Member', 'Board governance and reporting access.', true, 180),
  ('PARENT', 'Parent', 'Parent portal access for families.', true, 200),
  ('STUDENT', 'Student', 'Student portal access.', true, 210)
on conflict (name) do update set
