-- Mark official roles as system roles (immutable where column exists).
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'roles'
      and column_name = 'is_immutable'
  ) then
    update public.roles
    set is_immutable = true
    where name in (
      'FOUNDER',
      'EXECUTIVE_DIRECTOR',
      'SCHOOL_LEADER',
      'ADMINISTRATOR',
      'TEACHER',
      'PARENT',
      'STUDENT',
      'ACCOUNTING',
      'HR',
      'ADMISSIONS',
      'BOARD_MEMBER'
    );
  end if;
end $$;
-- <<< END SOURCE 160_enterprise_iam_official_platform_roles.sql

