-- =========================================
-- SPRINT 005: Official Platform Roles
-- Additive — does NOT remove existing roles (CEO, FINANCE, REGISTRAR, etc.)
-- =========================================

insert into public.roles (name, display_name, description, is_system, sort_order)
values
