-- >>> BEGIN SOURCE 199_email_domain_theacademyway.sql (blob 6dee2fd030f8e009a7072eed0198263b3412fd49)
-- =========================================
-- Align seed / founder emails to Academy Way domain
-- Outbound mail uses noreply@theacademyway.org (EMAIL_FROM).
-- Idempotent: rewrites legacy product-domain addresses only.
-- =========================================

update public.users
set email = regexp_replace(email, '@academyos\.org$', '@theacademyway.org', 'i')
where email ~* '@academyos\.org$';

update auth.users
set
  email = regexp_replace(email, '@academyos\.org$', '@theacademyway.org', 'i'),
  updated_at = now()
where email ~* '@academyos\.org$';

update auth.identities
set
  identity_data = case
    when coalesce(identity_data->>'email', '') ~* '@academyos\.org$'
      then jsonb_set(
        coalesce(identity_data, '{}'::jsonb),
        '{email}',
        to_jsonb(
          regexp_replace(
            identity_data->>'email',
            '@academyos\.org$',
            '@theacademyway.org',
            'i'
          )
        )
      )
    else identity_data
  end,
  provider_id = case
    when provider = 'email' and provider_id ~* '@academyos\.org$'
      then regexp_replace(provider_id, '@academyos\.org$', '@theacademyway.org', 'i')
    else provider_id
  end
where
  coalesce(identity_data->>'email', '') ~* '@academyos\.org$'
  or (provider = 'email' and provider_id ~* '@academyos\.org$');
-- <<< END SOURCE 199_email_domain_theacademyway.sql

-- >>> BEGIN SOURCE 200_sprint059_application_registry.sql (blob 0b03a0bff21a2452f039c0446d7596c7d92adcb4)
-- =========================================
-- SPRINT 059: APPLICATION REGISTRY & ENABLEMENT
-- Platform architecture track (Phase 1 — metadata only)
--
-- Teaches the platform about Applications:
--   Platform     = JAG
--   Application  = AcademyOS (Application #1)
--   Tenant       = Organization (The Academy Way = Tenant #1)
--   Enablement   = organization_applications
--
-- No UI / navigation / permission behavior changes in this sprint.
-- Idempotent: safe to re-run.
-- =========================================

-- ---------------------------------------------------------------------------
-- 1. Platform application catalog
-- ---------------------------------------------------------------------------

create table if not exists public.platform_applications (
  id uuid primary key default gen_random_uuid(),
  key text not null,
  name text not null,
  description text not null default '',
  status text not null default 'active'
    check (status in ('active', 'inactive', 'deprecated')),
  sort_order integer not null default 0,
  home_route text,
  permission_pack_key text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint platform_applications_key_unique unique (key)
);

drop trigger if exists platform_applications_set_updated_at
  on public.platform_applications;
create trigger platform_applications_set_updated_at
  before update on public.platform_applications
  for each row execute function public.trigger_set_updated_at();

create index if not exists idx_platform_applications_status_sort
  on public.platform_applications (status, sort_order);

comment on table public.platform_applications is
  'JAG platform application registry (AcademyOS, future HealthcareOS, …). Catalog only in Sprint 059.';

-- ---------------------------------------------------------------------------
-- 2. Tenant ↔ application enablement
-- ---------------------------------------------------------------------------

create table if not exists public.organization_applications (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null
    references public.org_organizations (id) on delete cascade,
  application_id uuid not null
    references public.platform_applications (id) on delete cascade,
  status text not null default 'enabled'
    check (status in ('enabled', 'disabled')),
  enabled_at timestamptz,
  disabled_at timestamptz,
  enabled_by uuid references public.users (id) on delete set null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint organization_applications_org_app_unique
    unique (organization_id, application_id)
);

drop trigger if exists organization_applications_set_updated_at
  on public.organization_applications;
create trigger organization_applications_set_updated_at
  before update on public.organization_applications
  for each row execute function public.trigger_set_updated_at();

create index if not exists idx_organization_applications_org
  on public.organization_applications (organization_id);

create index if not exists idx_organization_applications_app
  on public.organization_applications (application_id);

create index if not exists idx_organization_applications_enabled
  on public.organization_applications (organization_id, status)
  where status = 'enabled';

comment on table public.organization_applications is
  'Which applications are enabled for a tenant organization. Soft default in app code: missing rows ⇒ academyos enabled.';

-- ---------------------------------------------------------------------------
-- 3. Seed Application #1 = AcademyOS
-- ---------------------------------------------------------------------------

insert into public.platform_applications (
  key,
  name,
  description,
  status,
  sort_order,
  home_route,
  permission_pack_key,
  metadata
)
values (
  'academyos',
  'AcademyOS',
  'School / education operations application on the JAG platform.',
  'active',
  10,
  '/dashboard',
  'ACADEMYOS_ACCESS',
  jsonb_build_object(
    'application_number', 1,
    'vertical', 'education',
    'sprint', '059'
  )
)
on conflict (key) do update
set
  name = excluded.name,
  description = excluded.description,
  status = excluded.status,
  sort_order = excluded.sort_order,
  home_route = excluded.home_route,
  permission_pack_key = excluded.permission_pack_key,
  metadata = public.platform_applications.metadata || excluded.metadata,
  updated_at = now();

-- ---------------------------------------------------------------------------
-- 4. Enable AcademyOS for every existing tenant (incl. Tenant #1)
-- ---------------------------------------------------------------------------

insert into public.organization_applications (
  organization_id,
  application_id,
  status,
  enabled_at,
  metadata
)
select
  o.id,
  a.id,
  'enabled',
  now(),
  case
    when o.slug = 'the-academy-way' then jsonb_build_object(
      'tenant_number', 1,
      'tenant_name', 'The Academy Way',
      'sprint', '059'
    )
    else jsonb_build_object('sprint', '059', 'seeded', true)
  end
from public.org_organizations o
cross join public.platform_applications a
where a.key = 'academyos'
on conflict (organization_id, application_id) do update
set
  status = 'enabled',
  enabled_at = coalesce(public.organization_applications.enabled_at, now()),
  disabled_at = null,
  metadata = public.organization_applications.metadata || excluded.metadata,
  updated_at = now();

-- ---------------------------------------------------------------------------
-- 5. RLS
-- ---------------------------------------------------------------------------

alter table public.platform_applications enable row level security;
alter table public.organization_applications enable row level security;

-- Catalog: readable by authenticated users (like other platform type definitions)
drop policy if exists platform_applications_read on public.platform_applications;
create policy platform_applications_read
  on public.platform_applications
  for select to authenticated
  using (true);

-- Catalog writes: service role / SQL only (no authenticated write policy)

-- Enablement: org members (and platform stewards via can_access_organization) may read
drop policy if exists organization_applications_read
  on public.organization_applications;
create policy organization_applications_read
  on public.organization_applications
  for select to authenticated
  using (public.can_access_organization(organization_id));

-- Enablement manage: org admins only (not wired in UI this sprint)
drop policy if exists organization_applications_manage
  on public.organization_applications;
create policy organization_applications_manage
  on public.organization_applications
  for all to authenticated
  using (public.is_organization_admin(organization_id))
  with check (public.is_organization_admin(organization_id));

-- ---------------------------------------------------------------------------
-- 6. API grants + PostgREST reload
-- ---------------------------------------------------------------------------

grant select on public.platform_applications to authenticated, anon, service_role;
grant select, insert, update, delete on public.organization_applications
  to authenticated, service_role;
grant all on public.platform_applications to service_role;

notify pgrst, 'reload schema';
-- <<< END SOURCE 200_sprint059_application_registry.sql

-- >>> BEGIN SOURCE 211_organization_branding.sql (blob e9dc14b142d1625f32c0a2cd64115dd1826c8b83)
-- =========================================
-- Sprint 211 — Multi-tenant organization branding
-- Application-layer brand records (colors, logos, fonts, footers).
-- =========================================

create table if not exists public.organization_branding (
  id uuid primary key default gen_random_uuid(),
  organization_id text not null,
  subdomain text not null,
  organization_name text not null,
  display_name text not null,
  primary_color text not null default '#0F172A',
  secondary_color text not null default '#1E293B',
  accent_color text not null default '#0D9488',
  success_color text not null default '#059669',
  warning_color text not null default '#D97706',
  danger_color text not null default '#DC2626',
  light_logo_url text not null default '',
  dark_logo_url text not null default '',
  favicon_url text not null default '',
  app_icon_url text not null default '',
  heading_font text not null default 'Source Serif 4',
  body_font text not null default 'IBM Plex Sans',
  login_background_url text not null default '',
  dashboard_background_url text not null default '',
  email_footer text not null default '',
  pdf_footer text not null default '',
  powered_by_enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint organization_branding_organization_id_unique unique (organization_id),
  constraint organization_branding_subdomain_unique unique (subdomain)
);

create index if not exists idx_organization_branding_subdomain
  on public.organization_branding (subdomain);

create index if not exists idx_organization_branding_organization_id
  on public.organization_branding (organization_id);

-- -----------------------------------------
-- RLS
-- Authenticated members can read brands for orgs they can access.
-- Manage (insert/update/delete) for org admins / platform roles.
-- Falls back to authenticated read + manage when org helpers exist.
-- -----------------------------------------

alter table public.organization_branding enable row level security;

-- Read: any authenticated user with org access (or platform admin roles).
drop policy if exists organization_branding_select on public.organization_branding;
create policy organization_branding_select
  on public.organization_branding
  for select
  to authenticated
  using (
    auth.uid() is not null
    and (
      -- Platform operators
      (
        exists (
          select 1
          from public.user_roles ur
          join public.roles r on r.id = ur.role_id
          where ur.user_id = auth.uid()
            and r.name in ('FOUNDER', 'CEO', 'PLATFORM_ADMIN')
        )
      )
      -- Org membership when organization_id is a UUID
      or (
        organization_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and public.can_access_organization(organization_id::uuid)
      )
      -- Permissive authenticated read for demo / text org ids (Sprint 211).
      -- Tighten when all tenants use UUID organization ids.
      or true
    )
  );

-- Manage: authenticated users with org admin access (or platform roles).
drop policy if exists organization_branding_insert on public.organization_branding;
create policy organization_branding_insert
  on public.organization_branding
  for insert
  to authenticated
  with check (
    auth.uid() is not null
    and (
      exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.user_id = auth.uid()
          and r.name in ('FOUNDER', 'CEO', 'PLATFORM_ADMIN')
      )
      or (
        organization_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and public.is_organization_admin(organization_id::uuid)
      )
      -- Permissive authenticated manage for Sprint 211 bootstrap.
      or true
    )
  );

drop policy if exists organization_branding_update on public.organization_branding;
create policy organization_branding_update
  on public.organization_branding
  for update
  to authenticated
  using (
    auth.uid() is not null
    and (
      exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.user_id = auth.uid()
          and r.name in ('FOUNDER', 'CEO', 'PLATFORM_ADMIN')
      )
      or (
        organization_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and public.is_organization_admin(organization_id::uuid)
      )
      or true
    )
  )
  with check (
    auth.uid() is not null
  );

drop policy if exists organization_branding_delete on public.organization_branding;
create policy organization_branding_delete
  on public.organization_branding
  for delete
  to authenticated
  using (
    auth.uid() is not null
    and (
      exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.user_id = auth.uid()
          and r.name in ('FOUNDER', 'CEO', 'PLATFORM_ADMIN')
      )
      or (
        organization_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and public.is_organization_admin(organization_id::uuid)
      )
      or true
    )
  );

comment on table public.organization_branding is
  'Sprint 211 multi-tenant branding (colors, logos, fonts, footers). RLS: authenticated read/manage with org-admin preference; permissive bootstrap clause for demo org ids.';
-- <<< END SOURCE 211_organization_branding.sql

-- >>> BEGIN SOURCE 212_jag_org_scoped_authorization.sql (blob ad832ad3381a711cbb9aff07b1b159f7e78d61d8)
-- Sprint 212 — JAG External Pilot Foundation
-- Org-scoped JAG authorization + platform steward vs customer org admin.
-- Forward-only. Does not invite external pilots. Does not build /jag/admin UI.

-- ---------------------------------------------------------------------------
-- 1) Permissions (platform_permissions.permission_key)
-- ---------------------------------------------------------------------------
insert into public.platform_permissions (
  permission_key, name, description, module, category, sort_order
)
values
  (
    'JAG_PLATFORM_ADMIN',
    'JAG Platform Admin',
    'JAG platform control-plane administration across customer organizations.',
    'iam',
    'access',
    11
  ),
  (
    'JAG_ORG_ACCESS',
    'JAG Organization Access',
    'Org-scoped JAG workspace access for a customer organization administrator.',
    'iam',
    'access',
    12
  )
on conflict (permission_key) do update set
  name = excluded.name,
  description = excluded.description,
  module = excluded.module,
  category = excluded.category,
  sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- 2) Roles
-- ---------------------------------------------------------------------------
insert into public.roles (name, display_name, description, is_system, sort_order)
values
  (
    'PLATFORM_OWNER',
    'Platform Owner',
    'JAG platform control-plane steward (not a customer organization admin).',
    true,
    12
  ),
  (
    'JAG_ORG_ADMIN',
    'JAG Organization Admin',
    'Customer organization administrator with org-scoped JAG access.',
    true,
    45
  )
on conflict (name) do update set
  display_name = excluded.display_name,
  description = excluded.description,
  is_system = true,
  sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- 3) Role → permission grants (platform_role_permissions)
-- ---------------------------------------------------------------------------
insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name = 'PLATFORM_OWNER'
  and p.permission_key in (
    'JAG_ACCESS',
    'JAG_PLATFORM_ADMIN',
    'ACADEMYOS_ACCESS',
    'SYSTEM_ADMIN_ACCESS',
    'USER_MANAGEMENT_ACCESS',
    'AUDIT_ACCESS',
    'REPORTING_ACCESS',
    'org.view',
    'org.manage',
    'users.view',
    'users.manage',
    'mission_control.access',
    'executive.dashboard',
    'executive.intelligence',
    'search.global'
  )
on conflict (role_id, permission_key) do nothing;

-- Customer org admin — never JAG_ACCESS / JAG_PLATFORM_ADMIN / founder.*
insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name = 'JAG_ORG_ADMIN'
  and p.permission_key in (
    'JAG_ORG_ACCESS',
    'ACADEMYOS_ACCESS',
    'REPORTING_ACCESS',
    'org.view',
    'directory.view',
    'mission_control.access',
    'executive.dashboard',
    'executive.intelligence',
    'executive.risk_view',
    'search.global'
  )
on conflict (role_id, permission_key) do nothing;

-- Ensure FOUNDER retains the new catalog keys (already granted all via historical seed).
insert into public.platform_role_permissions (role_id, permission_key, effect)
select r.id, p.permission_key, 'allow'
from public.roles r
cross join public.platform_permissions p
where r.name = 'FOUNDER'
  and p.permission_key in ('JAG_PLATFORM_ADMIN', 'JAG_ORG_ACCESS')
on conflict (role_id, permission_key) do nothing;

-- ---------------------------------------------------------------------------
-- 4) Platform steward helper (FOUNDER or PLATFORM_OWNER)
-- ---------------------------------------------------------------------------
create or replace function public.is_platform_steward(check_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = check_user_id
      and r.name in ('FOUNDER', 'PLATFORM_OWNER')
  );
$$;

comment on function public.is_platform_steward(uuid) is
  'JAG/platform control-plane steward. Not granted to customer organization admins.';

-- ---------------------------------------------------------------------------
-- 5) Org access: stewards OR membership OR owner — CEO no longer global
-- ---------------------------------------------------------------------------
create or replace function public.user_can_access_organization(
  check_user_id uuid,
  check_organization_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    public.is_platform_steward(check_user_id)
    or exists (
      select 1
      from public.user_organization_memberships m
      where m.organization_id = check_organization_id
        and m.user_id = check_user_id
        and m.status = 'active'
    )
    or exists (
      select 1
      from public.org_organizations o
      where o.id = check_organization_id
        and o.owner_user_id = check_user_id
    );
$$;

comment on function public.user_can_access_organization(uuid, uuid) is
  'Organization access: platform steward (FOUNDER/PLATFORM_OWNER), active membership, or org owner. CEO is not globally privileged.';

-- ---------------------------------------------------------------------------
-- 6) Enterprise admin scoped to an organization
-- ---------------------------------------------------------------------------
create or replace function public.is_enterprise_admin_for_organization(
  check_organization_id uuid,
  check_user_id uuid default auth.uid()
)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    public.is_platform_steward(check_user_id)
    or (
      public.user_can_access_organization(check_user_id, check_organization_id)
      and exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.user_id = check_user_id
          and r.name in (
            'FOUNDER',
            'CEO',
            'EXECUTIVE_DIRECTOR',
            'JAG_ORG_ADMIN',
            'PLATFORM_OWNER'
          )
      )
    );
$$;

comment on function public.is_enterprise_admin_for_organization(uuid, uuid) is
  'Enterprise admin rights only within an accessible organization (or platform steward globally).';

-- Narrow legacy is_enterprise_admin: platform steward only (remove global CEO/ED).
create or replace function public.is_enterprise_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_platform_steward(auth.uid());
$$;

comment on function public.is_enterprise_admin() is
  'Global enterprise admin = platform steward only. CEO/ED must use org/school-scoped paths.';

-- ---------------------------------------------------------------------------
-- 7) Document auth provisioning contract for external pilots
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.auth_provisioning_config') is not null then
    comment on table public.auth_provisioning_config is
      'Auth user provisioning defaults. External pilot invites should set user_metadata.invite_organization_id or skip_default_org_membership=true to avoid auto-joining the-academy-way.';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 8) Users directory: stewards see all; others see self + co-members
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.users') is null then
    return;
  end if;

  if exists (
    select 1 from pg_policies
    where schemaname = 'public'
      and tablename = 'users'
      and policyname = 'users_select_access'
  ) then
    drop policy users_select_access on public.users;

    create policy users_select_access on public.users
      for select
      to authenticated
      using (
        public.is_platform_steward(auth.uid())
        or id = auth.uid()
        or exists (
          select 1
          from public.user_organization_memberships mine
          join public.user_organization_memberships theirs
            on theirs.organization_id = mine.organization_id
          where mine.user_id = auth.uid()
            and mine.status = 'active'
            and theirs.user_id = users.id
            and theirs.status = 'active'
        )
      );
  end if;
exception
  when undefined_table then null;
  when undefined_object then null;
  when insufficient_privilege then null;
end $$;

notify pgrst, 'reload schema';
